  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE concept (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "taxonomy" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "identifiers" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  "parent" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, taxonomy) REFERENCES taxonomy (tenant, id),
  FOREIGN KEY (tenant, identifiers) REFERENCES identifier_set (tenant, id),
  FOREIGN KEY (tenant, parent) REFERENCES concept (tenant, id)
);

CREATE TABLE concept_alias (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "taxonomy" TEXT NOT NULL,
  "alias" TEXT NOT NULL,
  "meaning" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, taxonomy) REFERENCES taxonomy (tenant, id),
  FOREIGN KEY (tenant, meaning) REFERENCES concept_revision (tenant, id)
);

CREATE TABLE concept_disposition (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "concept" TEXT NOT NULL,
  "replacement" TEXT,
  "effective_at" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, concept) REFERENCES concept (tenant, id),
  FOREIGN KEY (tenant, replacement) REFERENCES concept_revision (tenant, id)
);

CREATE TABLE concept_revision (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "concept" TEXT NOT NULL,
  "taxonomy" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "revision" INTEGER NOT NULL,
  "previous" TEXT,
  "parent_meaning" TEXT,
  "label" TEXT NOT NULL,
  "definition" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, concept) REFERENCES concept (tenant, id),
  FOREIGN KEY (tenant, taxonomy) REFERENCES taxonomy (tenant, id),
  FOREIGN KEY (tenant, previous) REFERENCES concept_revision (tenant, id),
  FOREIGN KEY (tenant, parent_meaning) REFERENCES concept_revision (tenant, id)
);

CREATE TABLE taxonomy (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "identifiers" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, identifiers) REFERENCES identifier_set (tenant, id)
);

CREATE TABLE attachment_link (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "thread" TEXT NOT NULL,
  "entry" TEXT NOT NULL,
  "revision" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, thread) REFERENCES thread (tenant, id),
  FOREIGN KEY (tenant, entry) REFERENCES thread_entry (tenant, id),
  FOREIGN KEY (tenant, revision) REFERENCES artifact_revision (tenant, id)
);

CREATE TABLE mention (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "thread" TEXT NOT NULL,
  "entry" TEXT NOT NULL,
  "participant" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, thread) REFERENCES thread (tenant, id),
  FOREIGN KEY (tenant, entry) REFERENCES thread_entry (tenant, id),
  FOREIGN KEY (tenant, participant) REFERENCES thread_participant (tenant, id)
);

CREATE TABLE reaction (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "thread" TEXT NOT NULL,
  "entry" TEXT NOT NULL,
  "author" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, thread) REFERENCES thread (tenant, id),
  FOREIGN KEY (tenant, entry) REFERENCES thread_entry (tenant, id),
  FOREIGN KEY (tenant, author) REFERENCES thread_participant (tenant, id)
);

CREATE TABLE thread (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "participants" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, participants) REFERENCES participation_set (tenant, id)
);

CREATE TABLE thread_entry (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "thread" TEXT NOT NULL,
  "author" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "corrects" TEXT,
  "recorded_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, thread) REFERENCES thread (tenant, id),
  FOREIGN KEY (tenant, author) REFERENCES thread_participant (tenant, id),
  FOREIGN KEY (tenant, corrects) REFERENCES thread_entry (tenant, id)
);

CREATE TABLE thread_event (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "thread" TEXT NOT NULL,
  "sequence" INTEGER NOT NULL,
  "previous" TEXT,
  "kind" TEXT NOT NULL,
  "actor" TEXT NOT NULL,
  "at" TEXT NOT NULL,
  "closed" INTEGER NOT NULL,
  "entry" TEXT,
  "reaction" TEXT,
  "mention" TEXT,
  "attachment" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, thread) REFERENCES thread (tenant, id),
  FOREIGN KEY (tenant, previous) REFERENCES thread_event (tenant, id),
  FOREIGN KEY (tenant, actor) REFERENCES thread_participant (tenant, id),
  FOREIGN KEY (tenant, entry) REFERENCES thread_entry (tenant, id),
  FOREIGN KEY (tenant, reaction) REFERENCES reaction (tenant, id),
  FOREIGN KEY (tenant, mention) REFERENCES mention (tenant, id),
  FOREIGN KEY (tenant, attachment) REFERENCES attachment_link (tenant, id)
);

CREATE TABLE thread_participant (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "thread" TEXT NOT NULL,
  "membership" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, thread) REFERENCES thread (tenant, id),
  FOREIGN KEY (tenant, membership) REFERENCES participation (tenant, id)
);

CREATE TABLE decision_case (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "participation_set" TEXT NOT NULL,
  "eligibility_at" TEXT NOT NULL,
  "electors" TEXT NOT NULL,
  "rule" TEXT NOT NULL,
  "rule_version" TEXT NOT NULL,
  "threshold" INTEGER NOT NULL,
  "option_count" INTEGER NOT NULL,
  "deadline" TEXT NOT NULL,
  "support" TEXT,
  "evaluation" TEXT,
  "reconsideration" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, participation_set) REFERENCES participation_set (tenant, id),
  FOREIGN KEY (tenant, electors) REFERENCES decision_elector (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id),
  FOREIGN KEY (tenant, evaluation) REFERENCES evaluation_finish (tenant, id),
  FOREIGN KEY (tenant, reconsideration) REFERENCES decision_case (tenant, id)
);

CREATE TABLE decision_elector (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "participation" TEXT NOT NULL,
  "ended" TEXT,
  "next" TEXT,
  "depth" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, participation) REFERENCES participation (tenant, id),
  FOREIGN KEY (tenant, ended) REFERENCES participation_end (tenant, id),
  FOREIGN KEY (tenant, next) REFERENCES decision_elector (tenant, id)
);

CREATE TABLE decision_event (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "decision_case" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "previous" TEXT,
  "kind" TEXT NOT NULL,
  "response" TEXT,
  "outcome" TEXT,
  "recorded_by" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, decision_case) REFERENCES decision_case (tenant, id),
  FOREIGN KEY (tenant, previous) REFERENCES decision_event (tenant, id),
  FOREIGN KEY (tenant, response) REFERENCES decision_response (tenant, id),
  FOREIGN KEY (tenant, outcome) REFERENCES decision_outcome (tenant, id)
);

CREATE TABLE decision_option (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "decision_case" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, decision_case) REFERENCES decision_case (tenant, id)
);

CREATE TABLE decision_outcome (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "decision_case" TEXT NOT NULL,
  "selected" TEXT NOT NULL,
  "responses" TEXT NOT NULL,
  "snapshot_digest" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, decision_case) REFERENCES decision_case (tenant, id),
  FOREIGN KEY (tenant, selected) REFERENCES decision_option (tenant, id),
  FOREIGN KEY (tenant, responses) REFERENCES decision_outcome_member (tenant, id)
);

CREATE TABLE decision_outcome_member (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "response" TEXT NOT NULL,
  "next" TEXT,
  "depth" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, response) REFERENCES decision_response (tenant, id),
  FOREIGN KEY (tenant, next) REFERENCES decision_outcome_member (tenant, id)
);

CREATE TABLE decision_response (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "decision_case" TEXT NOT NULL,
  "voter" TEXT NOT NULL,
  "ranking" TEXT NOT NULL,
  "support" TEXT,
  "recorded_by" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, decision_case) REFERENCES decision_case (tenant, id),
  FOREIGN KEY (tenant, voter) REFERENCES participation (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE delivery_attempt (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "step" TEXT NOT NULL,
  "started_at" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "provider_key" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, step) REFERENCES delivery_step (tenant, id)
);

CREATE TABLE delivery_destination (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE delivery_intent (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "destination" TEXT NOT NULL,
  "payload" TEXT,
  "max_attempts" INTEGER NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, destination) REFERENCES delivery_destination (tenant, id),
  FOREIGN KEY (tenant, payload) REFERENCES artifact_revision (tenant, id)
);

CREATE TABLE delivery_receipt (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "step" TEXT NOT NULL,
  "attempt" TEXT NOT NULL,
  "outcome" TEXT NOT NULL,
  "completed_at" TEXT NOT NULL,
  "provider_reference" TEXT NOT NULL,
  "callback_key" TEXT NOT NULL,
  "detail" TEXT NOT NULL,
  "support" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, step) REFERENCES delivery_step (tenant, id),
  FOREIGN KEY (tenant, attempt) REFERENCES delivery_attempt (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE delivery_resolution (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "receipt" TEXT NOT NULL,
  "outcome" TEXT NOT NULL,
  "resolved_at" TEXT NOT NULL,
  "detail" TEXT NOT NULL,
  "support" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, receipt) REFERENCES delivery_receipt (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE delivery_step (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "intent" TEXT NOT NULL,
  "number" INTEGER NOT NULL,
  "choice" TEXT NOT NULL,
  "previous" TEXT,
  "receipt" TEXT,
  "resolution" TEXT,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, intent) REFERENCES delivery_intent (tenant, id),
  FOREIGN KEY (tenant, previous) REFERENCES delivery_step (tenant, id),
  FOREIGN KEY (tenant, receipt) REFERENCES delivery_receipt (tenant, id),
  FOREIGN KEY (tenant, resolution) REFERENCES delivery_resolution (tenant, id)
);

CREATE TABLE entitlement (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "holder" TEXT NOT NULL,
  "right_" TEXT NOT NULL,
  "scope" TEXT NOT NULL,
  "quantity" INTEGER,
  "unit" TEXT,
  "valid_from" TEXT NOT NULL,
  "valid_until" TEXT,
  "predecessor" TEXT,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, holder) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, right_) REFERENCES right_definition (tenant, id),
  FOREIGN KEY (tenant, scope) REFERENCES entitlement_scope (tenant, id),
  FOREIGN KEY (tenant, predecessor) REFERENCES entitlement (tenant, id)
);

CREATE TABLE entitlement_end (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "entitlement" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, entitlement) REFERENCES entitlement (tenant, id)
);

CREATE TABLE entitlement_scope (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE obligation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "obligated_party" TEXT NOT NULL,
  "requirement" TEXT NOT NULL,
  "scope" TEXT NOT NULL,
  "quantity" INTEGER,
  "unit" TEXT,
  "incurred_at" TEXT NOT NULL,
  "due_at" TEXT,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, obligated_party) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, requirement) REFERENCES requirement_definition (tenant, id),
  FOREIGN KEY (tenant, scope) REFERENCES entitlement_scope (tenant, id)
);

CREATE TABLE obligation_end (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "obligation" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, obligation) REFERENCES obligation (tenant, id)
);

CREATE TABLE requirement_definition (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "namespace" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE right_definition (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "namespace" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE evaluation_executor (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE evaluation_finish (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "run" TEXT NOT NULL,
  "start" TEXT,
  "outcome" TEXT NOT NULL,
  "finished_at" TEXT NOT NULL,
  "support" TEXT,
  "reason" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, run) REFERENCES evaluation_run (tenant, id),
  FOREIGN KEY (tenant, start) REFERENCES evaluation_start (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE evaluation_quarantine (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "run" TEXT NOT NULL,
  "source_digest" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, run) REFERENCES evaluation_run (tenant, id)
);

CREATE TABLE evaluation_run (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "evaluation_set" TEXT NOT NULL,
  "definition" TEXT NOT NULL,
  "executor" TEXT NOT NULL,
  "parent" TEXT,
  "depth" INTEGER NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, evaluation_set) REFERENCES evaluation_set (tenant, id),
  FOREIGN KEY (tenant, definition) REFERENCES specification_pin (tenant, id),
  FOREIGN KEY (tenant, executor) REFERENCES evaluation_executor (tenant, id),
  FOREIGN KEY (tenant, parent) REFERENCES evaluation_run (tenant, id)
);

CREATE TABLE evaluation_set (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE evaluation_start (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "run" TEXT NOT NULL,
  "started_at" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, run) REFERENCES evaluation_run (tenant, id)
);

CREATE TABLE evidence_bundle (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "predecessor" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, predecessor) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE evidence_item (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "bundle" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "source_record" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "observed_at" TEXT NOT NULL,
  "revision" TEXT,
  "digest" TEXT,
  "provenance" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, bundle) REFERENCES evidence_bundle (tenant, id),
  FOREIGN KEY (tenant, source) REFERENCES evidence_source (tenant, id),
  FOREIGN KEY (tenant, revision) REFERENCES artifact_revision (tenant, id)
);

CREATE TABLE evidence_member (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "bundle" TEXT NOT NULL,
  "item" TEXT NOT NULL,
  "next" TEXT,
  "depth" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, bundle) REFERENCES evidence_bundle (tenant, id),
  FOREIGN KEY (tenant, item) REFERENCES evidence_item (tenant, id),
  FOREIGN KEY (tenant, next) REFERENCES evidence_member (tenant, id)
);

CREATE TABLE evidence_seal (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "bundle" TEXT NOT NULL,
  "head" TEXT,
  "recorded_by" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, bundle) REFERENCES evidence_bundle (tenant, id),
  FOREIGN KEY (tenant, head) REFERENCES evidence_member (tenant, id)
);

CREATE TABLE evidence_source (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE fulfillment (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "fulfillment_set" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "specification_pin" TEXT,
  "executor" TEXT NOT NULL,
  "requested_at" TEXT NOT NULL,
  "evidence" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, fulfillment_set) REFERENCES fulfillment_set (tenant, id),
  FOREIGN KEY (tenant, specification_pin) REFERENCES specification_pin (tenant, id),
  FOREIGN KEY (tenant, executor) REFERENCES fulfillment_executor (tenant, id),
  FOREIGN KEY (tenant, evidence) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE fulfillment_end (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "fulfillment" TEXT NOT NULL,
  "start" TEXT,
  "outcome" TEXT NOT NULL,
  "coverage" TEXT NOT NULL,
  "ended_at" TEXT NOT NULL,
  "evidence" TEXT,
  "reason" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, fulfillment) REFERENCES fulfillment (tenant, id),
  FOREIGN KEY (tenant, start) REFERENCES fulfillment_start (tenant, id),
  FOREIGN KEY (tenant, evidence) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE fulfillment_executor (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE fulfillment_replacement (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "prior" TEXT NOT NULL,
  "prior_end" TEXT NOT NULL,
  "replacement" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, prior) REFERENCES fulfillment (tenant, id),
  FOREIGN KEY (tenant, prior_end) REFERENCES fulfillment_end (tenant, id),
  FOREIGN KEY (tenant, replacement) REFERENCES fulfillment (tenant, id)
);

CREATE TABLE fulfillment_set (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE fulfillment_start (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "fulfillment" TEXT NOT NULL,
  "began_at" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, fulfillment) REFERENCES fulfillment (tenant, id)
);

CREATE TABLE fulfillment_task_link (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "fulfillment" TEXT NOT NULL,
  "queue" TEXT NOT NULL,
  "task" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, fulfillment) REFERENCES fulfillment (tenant, id)
);

CREATE TABLE identifier (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "identifier_set" TEXT NOT NULL,
  "namespace" TEXT NOT NULL,
  "issuer" TEXT,
  "issuer_scope" TEXT NOT NULL,
  "value_" TEXT NOT NULL,
  "valid_from" TEXT NOT NULL,
  "valid_until" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, identifier_set) REFERENCES identifier_set (tenant, id),
  FOREIGN KEY (tenant, issuer) REFERENCES issuer (tenant, id)
);

CREATE TABLE identifier_disposition (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "identifier" TEXT NOT NULL,
  "replacement" TEXT,
  "effective_at" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, identifier) REFERENCES identifier (tenant, id),
  FOREIGN KEY (tenant, replacement) REFERENCES identifier (tenant, id)
);

CREATE TABLE identifier_set (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE issuer (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE account (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "book" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "unit" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, book) REFERENCES ledger_book (tenant, id)
);

CREATE TABLE entry (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "book" TEXT NOT NULL,
  "account" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "next" TEXT,
